-- Slate (tittel-platform) schema — Supabase Postgres.
-- Idempotent: safe to run repeatedly (applied on every boot, see server/migrate.ts).
-- Shape is authoritative in PLAN.md §5 — keep this file and that section in sync.
--
-- Conventions: id = nanoid text PK generated by the app (packages/shared), not a
-- DB default. created_at timestamptz default now() everywhere. Every tenant-owned
-- table carries org_id with an index. Soft-delete via archived_at where noted.

-- =============================================================================
-- 5.1 Tenancy & identity
-- =============================================================================

create table if not exists orgs (
  id                     text primary key,
  name                   text not null,
  plan                   text not null default 'trial'
                         check (plan in ('trial','solo','studio','free')),
  trial_ends_at          timestamptz,
  stripe_customer_id     text,
  stripe_subscription_id text,
  settings               jsonb not null default '{}',
  created_at             timestamptz not null default now()
);

create table if not exists users (
  id            text primary key,
  org_id        text not null references orgs(id) on delete cascade,
  supabase_uid  text not null unique,
  email         text not null,
  display_name  text,
  role          text not null default 'owner' check (role in ('owner','tutor')),
  created_at    timestamptz not null default now()
);
create index if not exists users_org_idx on users(org_id);

create table if not exists students (
  id            text primary key,
  org_id        text not null references orgs(id) on delete cascade,
  name          text not null,
  email         text,
  portal_token  text not null unique,
  report_token  text unique,
  notes         text,
  archived_at   timestamptz,
  created_at    timestamptz not null default now()
);
create index if not exists students_org_idx on students(org_id);

-- A student's email addresses: their own (school, personal) and their
-- parents'. Calendar invites to any of them are this student's lessons
-- (FLOW-SPEC §9.2). The same parent address may sit on siblings.
-- Supersedes students.email / students.parent_email (backfilled below).
create table if not exists student_emails (
  student_id text not null references students(id) on delete cascade,
  org_id     text not null references orgs(id) on delete cascade,
  email      text not null,
  role       text not null check (role in ('student', 'parent')),
  created_at timestamptz not null default now(),
  primary key (student_id, email)
);
create index if not exists student_emails_org_idx on student_emails(org_id, email);

create table if not exists groups (
  id          text primary key,
  org_id      text not null references orgs(id) on delete cascade,
  name        text not null,
  archived_at timestamptz,
  created_at  timestamptz not null default now()
);
create index if not exists groups_org_idx on groups(org_id);

create table if not exists group_members (
  group_id   text not null references groups(id) on delete cascade,
  student_id text not null references students(id) on delete cascade,
  primary key (group_id, student_id)
);

-- =============================================================================
-- 5.2 Content
-- =============================================================================

create table if not exists tags (
  id        text primary key,
  org_id    text not null references orgs(id) on delete cascade,
  name      text not null,
  parent_id text references tags(id) on delete set null
);
create index if not exists tags_org_idx on tags(org_id);

create table if not exists problems (
  id                 text primary key,
  org_id             text not null references orgs(id) on delete cascade,
  type               text not null check (type in ('mc','multi','numeric','text','frq')),
  stem_latex         text not null,
  choices            jsonb not null default '[]',
  correct            jsonb,
  accept             jsonb not null default '[]',
  explanation_latex  text,
  figures            jsonb not null default '[]',
  difficulty         int,
  source             text,
  archived_at        timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index if not exists problems_org_idx on problems(org_id);

create table if not exists problem_tags (
  problem_id text not null references problems(id) on delete cascade,
  tag_id     text not null references tags(id) on delete cascade,
  primary key (problem_id, tag_id)
);

create table if not exists problem_sets (
  id          text primary key,
  org_id      text not null references orgs(id) on delete cascade,
  title       text not null,
  description text,
  template    text not null default 'neutral' check (template in ('neutral','sat')),
  archived_at timestamptz,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index if not exists problem_sets_org_idx on problem_sets(org_id);

create table if not exists set_problems (
  set_id     text not null references problem_sets(id) on delete cascade,
  problem_id text not null references problems(id) on delete cascade,
  ordinal    int not null,
  primary key (set_id, problem_id)
);
create index if not exists set_problems_set_idx on set_problems(set_id, ordinal);

create table if not exists lessons (
  id          text primary key,
  org_id      text not null references orgs(id) on delete cascade,
  title       text not null,
  doc         jsonb not null default '{}',
  version     int not null default 1,
  archived_at timestamptz,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index if not exists lessons_org_idx on lessons(org_id);

create table if not exists lesson_tags (
  lesson_id text not null references lessons(id) on delete cascade,
  tag_id    text not null references tags(id) on delete cascade,
  primary key (lesson_id, tag_id)
);

-- =============================================================================
-- 5.3 Assignments & attempts
-- =============================================================================

create table if not exists assignments (
  id             text primary key,
  org_id         text not null references orgs(id) on delete cascade,
  set_id         text not null references problem_sets(id),
  title          text,
  time_limit_sec int,                        -- null = untimed
  due_at         timestamptz,
  settings       jsonb not null default '{}',
  created_by     text references users(id),
  archived_at    timestamptz,
  created_at     timestamptz not null default now()
);
create index if not exists assignments_org_idx on assignments(org_id);

create table if not exists assignment_student (
  assignment_id text not null references assignments(id) on delete cascade,
  student_id    text not null references students(id) on delete cascade,
  primary key (assignment_id, student_id)
);

-- The assignment's own copy of its set's problem list, taken at creation.
-- Editing the set afterwards (add/remove/reorder) changes only future
-- assignments; already-assigned homework, its scores and its review stay put.
-- Problem *content* is not copied, so fixing a typo in a problem still reaches
-- everyone who has it.
create table if not exists assignment_problems (
  assignment_id text not null references assignments(id) on delete cascade,
  problem_id    text not null references problems(id),
  ordinal       int not null,
  primary key (assignment_id, problem_id)
);
create index if not exists assignment_problems_ord_idx on assignment_problems(assignment_id, ordinal);

create table if not exists attempts (
  id             text primary key,
  org_id         text not null references orgs(id) on delete cascade,
  assignment_id  text not null references assignments(id) on delete cascade,
  student_id     text not null references students(id) on delete cascade,
  attempt_token  text not null unique,
  started_at     timestamptz,
  submitted_at   timestamptz,
  status         text not null default 'pending'
                 check (status in ('pending','active','submitted','expired')),
  unique (assignment_id, student_id)
);
create index if not exists attempts_org_idx on attempts(org_id);

create table if not exists responses (
  id                text primary key,
  attempt_id        text not null references attempts(id) on delete cascade,
  problem_id        text not null references problems(id),
  answer            jsonb,
  is_correct        boolean,
  marked_for_review boolean not null default false,
  time_spent_ms     int not null default 0,
  change_count      int not null default 0,
  updated_at        timestamptz not null default now(),
  unique (attempt_id, problem_id)
);

-- =============================================================================
-- 5.4 Live teaching
-- =============================================================================

create table if not exists classes (
  id          text primary key,
  org_id      text not null references orgs(id) on delete cascade,
  name        text not null,
  slug        text not null,
  mode        text not null default 'individual' check (mode in ('individual','large')),
  group_id    text references groups(id) on delete set null,
  archived_at timestamptz,
  unique (org_id, slug)
);
create index if not exists classes_org_idx on classes(org_id);

-- A weekly lesson slot (FLOW-SPEC §4). Its occurrences are materialised as
-- `sessions` rows a few weeks ahead, lazily, whenever the schedule is read.
-- weekday/start_time are local to `tz`, so 4pm stays 4pm across DST.
create table if not exists lesson_series (
  id           text primary key,
  org_id       text not null references orgs(id) on delete cascade,
  student_id   text references students(id) on delete cascade,
  group_id     text references groups(id) on delete cascade,
  weekday      int not null check (weekday between 0 and 6),   -- 0 = Sunday
  start_time   time not null,
  duration_min int not null,
  tz           text not null,
  starts_on    date not null,
  meeting_url  text,
  archived_at  timestamptz,
  created_at   timestamptz not null default now()
);
create index if not exists lesson_series_org_idx on lesson_series(org_id);

-- Google Calendar import (FLOW-SPEC §3 B): what the tutor told us about an
-- event series the importer couldn't match by email ("this is Maya", or
-- "not a lesson"). Keyed by the series' iCal UID, so it holds for every
-- week of a recurring event.
create table if not exists calendar_links (
  org_id     text not null references orgs(id) on delete cascade,
  uid        text not null,
  student_id text references students(id) on delete cascade,
  group_id   text references groups(id) on delete cascade,
  ignored    boolean not null default false,
  created_at timestamptz not null default now(),
  primary key (org_id, uid)
);

create table if not exists boards (
  id                  text primary key,
  org_id              text not null references orgs(id) on delete cascade,
  title               text,
  class_id            text references classes(id) on delete set null,
  student_id          text references students(id) on delete set null,
  snapshot            jsonb,
  snapshot_updated_at timestamptz,
  lesson_id           text references lessons(id) on delete set null,
  is_ephemeral        boolean not null default false,
  archived_at         timestamptz,
  created_at          timestamptz not null default now()
);
create index if not exists boards_org_idx on boards(org_id);

create table if not exists board_assets (
  id          text primary key,
  board_id    text not null references boards(id) on delete cascade,
  org_id      text not null references orgs(id) on delete cascade,
  storage_key text not null,
  mime        text not null,
  created_at  timestamptz not null default now()
);
create index if not exists board_assets_org_idx on board_assets(org_id);

create table if not exists sessions (
  id               text primary key,
  org_id           text not null references orgs(id) on delete cascade,
  board_id         text not null references boards(id) on delete cascade,
  started_at       timestamptz not null default now(),
  ended_at         timestamptz,
  participants     jsonb not null default '[]',
  quiz_results     jsonb,
  pdf_storage_key  text
);
create index if not exists sessions_org_idx on sessions(org_id);

create table if not exists quiz_events (
  id          text primary key,
  org_id      text not null references orgs(id) on delete cascade,
  session_id  text not null references sessions(id) on delete cascade,
  student_id  text references students(id) on delete set null,
  guest_name  text,
  qid         text not null,
  answer      jsonb,
  is_correct  boolean,
  elapsed_ms  int,
  created_at  timestamptz not null default now()
);
create index if not exists quiz_events_org_idx on quiz_events(org_id);

-- =============================================================================
-- migrations (idempotent)
-- =============================================================================
-- `create table if not exists` above does nothing for columns added to a table
-- that already exists on a deployed DB. Every new column needs an idempotent
-- `alter table ... add column if not exists ...` here too.

alter table lessons add column if not exists created_at timestamptz not null default now();

-- Backfill: assignments created before assignment_problems existed snapshot
-- their set as it is now. Only touches assignments with no rows yet, so
-- re-running is a no-op.
insert into assignment_problems (assignment_id, problem_id, ordinal)
select a.id, sp.problem_id, sp.ordinal
  from assignments a
  join set_problems sp on sp.set_id = a.set_id
 where not exists (select 1 from assignment_problems ap where ap.assignment_id = a.id)
on conflict do nothing;

-- FLOW-SPEC §4: a `sessions` row is now a Lesson — scheduled first, live
-- while taught, past after. A scheduled lesson has no board or start yet.
-- (UI word "Lesson" = this table; UI word "Plan" = the `lessons` table.)
alter table sessions alter column board_id drop not null;
alter table sessions alter column started_at drop not null;
alter table sessions add column if not exists student_id   text references students(id) on delete cascade;
alter table sessions add column if not exists group_id     text references groups(id) on delete cascade;
alter table sessions add column if not exists series_id    text references lesson_series(id) on delete set null;
alter table sessions add column if not exists scheduled_at timestamptz;
alter table sessions add column if not exists duration_min int;
alter table sessions add column if not exists status       text not null default 'scheduled';  -- scheduled | live | cancelled
alter table sessions add column if not exists meeting_url  text;
alter table sessions add column if not exists plan_id      text references lessons(id) on delete set null;
alter table sessions add column if not exists notes        text;
create index if not exists sessions_org_sched_idx on sessions(org_id, scheduled_at);

-- Homework given at a lesson; its default due date is the next lesson.
alter table assignments add column if not exists session_id text references sessions(id) on delete set null;

-- Per-student meeting link; falls back to the tutor's default in orgs.settings.
alter table students add column if not exists meeting_url text;

-- FLOW-SPEC F2: lessons imported from Google Calendar. calendar_uid is one
-- occurrence (series UID + original start); the calendar owns its time and
-- status, the tutor still owns its plan, homework, notes and meeting
-- override. calendar_meeting_url is the event's own link, kept apart from
-- meeting_url so a sync never overwrites the tutor's override.
alter table sessions add column if not exists calendar_uid text;
alter table sessions add column if not exists calendar_meeting_url text;
create unique index if not exists sessions_org_calendar_uid on sessions(org_id, calendar_uid) where calendar_uid is not null;

-- Tutor-owned parent contact (OVERHAUL R7); also how a parent-invited
-- calendar event is matched to a younger student.
alter table students add column if not exists parent_email text;

-- student_emails replaces the single email/parent_email columns. Move any
-- address still in them into the table, then clear them: the app no longer
-- reads or writes them, and clearing keeps this re-runnable without
-- resurrecting an address the tutor later removed.
insert into student_emails (student_id, org_id, email, role)
select id, org_id, lower(trim(email)), 'student' from students where email is not null and trim(email) <> ''
on conflict do nothing;
insert into student_emails (student_id, org_id, email, role)
select id, org_id, lower(trim(parent_email)), 'parent' from students where parent_email is not null and trim(parent_email) <> ''
on conflict do nothing;
update students set email = null where email is not null;
update students set parent_email = null where parent_email is not null;
